pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testRegression_property() public {
        // Setup: user A deposits 1 ether
        address userA = address(0x1234);
        vm.deal(userA, 1 ether);
        vm.prank(userA);
        c.Deposit{value: 1 ether}();

        // Now, user A calls CashOut(1 ether) - this should decrease A's balance to 0 in reference, increase to 2 in buggy
        // But we check a different key: user B's balance should remain 0 in both (since B never deposits)
        address userB = address(0x5678);
        vm.startPrank(userA);
        c.CashOut(1 ether);
        vm.stopPrank();

        // Assert: userB's balance is still 0 in reference, but in buggy it may have changed due to the addition bug
        // Actually, the bug only affects the caller's balance. So userB's balance remains 0 in both.
        // We need a scenario where a non-caller's balance differs.
        // Let's try: userA deposits, then userB calls CashOut with an amount that should be subtracted from userA? No, CashOut only affects caller.
        // The mutation changes balances[msg.sender] from subtraction to addition, so only the caller's balance changes.
        // To have a differing key that is not the caller, we need a deposit by userA, then userB calls CashOut(0).
        // In reference: userB's balance = 0 - 0 = 0; in buggy: userB's balance = 0 + 0 = 0. No difference.
        // So we must check the caller's balance. The task says "the differing key need not be the caller's own", but it can be.
        // Let's check userA's balance after userA calls CashOut(1 ether).
        uint256 balanceA = c.balances(userA);
        // Reference: 1 - 1 = 0; Buggy: 1 + 1 = 2
        assertTrue(balanceA == 0, "Reference: balance should be 0; Bug: would be 2");
    }
}

