        c.Deposit{value: 2 ether}();
        // First CashOut: 1 ether (subtraction in ref, addition in bug)
        c.CashOut(1 ether);
        // Second CashOut: 1 ether
        c.CashOut(1 ether);
        vm.stopPrank();

        // Reference: after two subtractions, balance = 2 - 1 - 1 = 0
