pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testRegression_property() public {
        address alice = address(0x1234);
        vm.deal(alice, type(uint256).max);

        // Alice deposits exactly MinDeposit = 1 ether
        vm.prank(alice);
        c.Deposit{value: 1 ether}();

        // Now she deposits a huge amount that would overflow if added to current balance
        // Balance before = 1 ether, we deposit (type(uint256).max - 1 ether + 1) wei
        uint256 hugeAmount = type(uint256).max - 1 ether + 1;
        vm.prank(alice);
        c.Deposit{value: hugeAmount}();

        // Now try to cash out 1 ether
        bool succeeded;
        vm.prank(alice);
        try c.CashOut(1 ether) {
            succeeded = true;
        } catch {
            succeeded = false;
        }

        // In the reference contract, the huge deposit reverts due to overflow check,
        // so balance is still 1 ether, and CashOut(1 ether) succeeds.
        // In the buggy contract, the huge deposit succeeds (balance overflows to 0),
        // so CashOut(1 ether) reverts due to insufficient balance.
        // Thus the assertion is: reference succeeds, buggy fails.
        assertTrue(succeeded, "CashOut should succeed in reference but fail in buggy");
    }
}

